parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "mode": {
      "type": "string",
      "enum": [
        "apply",
        "chat",
        "browse"
      ]
    },
    "goal": {
      "type": "string",
      "description": "Короткая цель одним предложением."
    },
    "start_url": {
      "type": "string",
      "description": "Адрес из запроса или пустая строка."
    },
    "target_count": {
      "type": "integer",
      "description": "Сколько раз выполнить, иначе 0."
    },
    "criteria": {
      "type": "string",
      "description": "Критерии отбора вакансий или пустая строка."
    }
  },
  "required": [
    "mode",
    "goal",
    "start_url",
    "target_count",
    "criteria"
  ]
}

parameters.jsCode:
// Объединяем: то, что задано в «Задании» > то, что надёжно находится кодом > ответ «Планировщика» > значения по умолчанию
const getCtx = (name) => {
  let lastErr;
  for (const suffix of ['', '1', '2', '3', '4', '5']) {
    const n = name + suffix;
    try { return $(n).item.json; } catch (e) { lastErr = e; }
    try { return $(n).first().json; } catch (e) { lastErr = e; }
  }
  throw lastErr;
};

const st = getCtx('Задание');
const plan = ($input.item.json && $input.item.json.output && typeof $input.item.json.output === 'object') ? $input.item.json.output : {};
const req = String(st.user_request || '');

const KNOWN_SITES = [
  [/telegram|телеграм|t\.me/i, 'https://web.telegram.org/a/'],
  [/youtube|ютуб|ютьюб/i, 'https://www.youtube.com/'],
  [/google|гугл/i, 'https://www.google.com/'],
  [/hh\.ru|headhunter|хх\.ру/i, 'https://hh.ru/']
];

// --- режим ---
let mode = String(st.mode || '').trim();
if (!['apply', 'chat', 'browse'].includes(mode)) {
  if (/(telegram|телеграм|t\.me|@\w*bot\b|мессенджер|переписк)/i.test(req)) mode = 'chat';
  else if (/(вакан|отклик|hh\.ru|headhunter|резюме)/i.test(req)) mode = 'apply';
  else mode = ['apply', 'chat', 'browse'].includes(plan.mode) ? plan.mode : 'browse';
}

// --- адрес ---
const urlInReq = (req.match(/https?:\/\/[^\s)»"]+/) || [])[0] || '';
let startUrl = String(st.start_url || '').trim() || urlInReq;
if (!startUrl && /^https?:\/\//i.test(String(plan.start_url || ''))) startUrl = plan.start_url;
if (!startUrl) { const k = KNOWN_SITES.find(([re]) => re.test(req)); if (k) startUrl = k[1]; }

// --- сколько раз ---
let count = Number(st.target_count || 0);
if (!count) { const m = req.match(/(\d+)\s*(?:раз|откликов|отклика|отклик|вакансий|вакансии|сообщений|ответов|шт)/i); if (m) count = Number(m[1]); }
if (!count) count = Number(plan.target_count || 0);
if (!count) count = { apply: 10, chat: 20, browse: 0 }[mode];
if (mode === 'browse') count = 0;

// --- история обработанных вакансий из прошлых запусков (только у активного workflow) ---
let saved = [];
try {
  const sd = $getWorkflowStaticData('global');
  saved = Array.isArray(sd.visited_ids) ? sd.visited_ids.map(String) : [];
} catch (e) { /* нет статических данных — не страшно */ }
const own = Array.isArray(st.visited_ids) ? st.visited_ids.map(String) : [];
const visited = Array.from(new Set(saved.concat(own))).slice(-2000);

return {
  json: {
    ...st,
    mode,
    goal: String(plan.goal || '').trim() || req,
    start_url: startUrl,
    list_url: startUrl,
    target_count: count,
    criteria: String(st.criteria || plan.criteria || ''),
    visited_ids: visited
  }
};

// ===== Настройки =====
const SINGLE_MAX_STEPS = 30;     // лимит шагов в обычном режиме
const STEPS_PER_ITEM = 20;       // режим откликов/чата: шагов на один отклик
const BASE_STEPS = 15;           // запас шагов
const HISTORY_SHOWN = 3;         // сколько последних действий видит «Решатель»
const DECIDE_MAX_ELEMENTS = 35;  // сколько элементов видит «Решатель»
const DECIDE_MAX_LINKS = 15;     // из них ссылок
const PROFILE_CHARS = 3500;      // длина профиля для «Писателя»
const WRITE_LETTER_ALWAYS = true;// писать сопроводительное, даже если оно не обязательно (если есть кнопка)
const MAX_TYPE_ATTEMPTS = 3;     // сколько раз пробуем вписать в одно поле
const CHAT_MAX_WAITS = 12;       // сколько шагов ждать ответа собеседника

// ===== Настройки под сайт (hh.ru, русский + английский интерфейс) =====
const ITEM_HREF_RE = /\/vacancy\/(\d+)/;
const ITEM_URL_RE = /(?:\/vacancy\/|vacancyId=|vacancy_id=)(\d+)/i;
const FORM_URL_RE = /vacancy_response|\/apply/i;
const LIST_URL_RE = /\/search\//i;
const SUCCESS_RE = /(вы откликнулись|отклик отправлен|резюме доставлено|ваш отклик отправлен|application sent|responded|response sent|you have applied|resume delivered)/i;
const BLOCK_RE = /(я не робот|captcha|капч|подтвердите, что вы не робот|введите код из|verify you are human)/i;
const LETTER_REQUIRED_RE = /(сопроводительн\S* письм\S*[^.]{0,80}обязательн|обязательн\S*[^.]{0,80}сопроводительн|cover letter is mandatory|please enter cover letter|cover letter is required)/i;
const LETTER_FIELD_RE = /(letter|сопроводит|covering)/i;
const LETTER_TOGGLE_RE = /(((написать|добавить|приложить|write|add|attach).{0,30}(сопроводит|cover))|letter-toggle)/i;
const APPLY_RE = /^(откликнуться|respond|apply|отправить отклик)/i;
const APPLY_DQ_RE = /vacancy-response-link/i;
const SUBMIT_RE = /^(откликнуться|отправить( отклик)?|respond|send( application)?|submit|apply|продолжить|continue)/i;
const NEXT_RE = /^(дальше|далее|следующая|next)/i;
const NEXT_DQ_RE = /pager-next/i;
const CHAT_INPUT_RE = /(message|сообщен|напишите)/i;

const getCtx = (name) => {
  let lastErr;
  for (const suffix of ['', '1', '2', '3', '4', '5']) {
    const n = name + suffix;
    try { return $(n).item.json; } catch (e) { lastErr = e; }
    try { return $(n).first().json; } catch (e) { lastErr = e; }
  }
  throw lastErr;
};

const st = getCtx('Начало шага');
const res = $input.item.json || {};
const snap = res.snapshot || {};
const url = res.current_url || '';
const els = Array.isArray(snap.elements) ? snap.elements : [];
const pageText = String(snap.text || '');
const title = String(snap.title || '');
const h1 = String(snap.h1 || '');
const tail = String(snap.tail || '');

const mode = st.mode || 'browse';
const targetCount = Number(st.target_count || 0);
const batch = targetCount > 0 && mode !== 'browse';
const doneCount = Number(st.done_count || 0);
const skippedCount = Number(st.skipped_count || 0);
const visited = Array.isArray(st.visited_ids) ? st.visited_ids.map(String) : [];
const history = Array.isArray(st.history_of_actions) ? st.history_of_actions : [];
const signatures = Array.isArray(st.signatures) ? st.signatures : [];
const typeCounts = st.type_counts && typeof st.type_counts === 'object' ? st.type_counts : {};
const step = Number(st.step || 0);
const maxSteps = batch ? targetCount * STEPS_PER_ITEM + BASE_STEPS : SINGLE_MAX_STEPS;
const engaged = !!st.engaged;

const cut = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const hash = (str) => { let h = 5381; for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) | 0; return String(h); };
const normText = (s) => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '');
const isEmpty = (e) => !String(e.value || '').trim();
const pathOf = (href) => { const m = String(href || '').match(/^https?:\/\/[^\/]+(\/[^?#]*)/); return m ? m[1] : String(href || ''); };

// ===== Что за страница =====
const idMatch = url.match(ITEM_URL_RE);
const vacId = idMatch ? idMatch[1] : (engaged ? String(st.current_vacancy_id || '') : '');
const itemLinks = els.filter((e) => {
  if (e.kind !== 'link' || !e.href) return false;
  const m = e.href.match(ITEM_HREF_RE);
  return m && !visited.includes(m[1]);
});
let pageKind = 'другая страница';
if (!url) pageKind = 'браузер пуст';
else if (idMatch) pageKind = FORM_URL_RE.test(url) ? 'форма отклика' : 'страница вакансии';
else if (itemLinks.length >= 1 || LIST_URL_RE.test(url)) pageKind = 'список вакансий';

const successSeen = SUCCESS_RE.test(pageText);
const blocked = BLOCK_RE.test(pageText);
const autoDone = mode === 'apply' && batch && !!vacId && engaged && successSeen;

// ===== Что изменилось после последнего действия =====
const fingerprint = url + '|' + hash(els.map((e) => `${e.kind}${e.label}${e.value || ''}${e.chk || ''}`).join('|') + pageText.length);
const lastAction = st.last_action || '';
const lastUrl = st.last_url || '';
const NAV_ACTIONS = ['click', 'open_url', 'skip', 'done'];
const prevNoChange = Number(st.no_change_count || 0);
const changed = fingerprint !== (st.last_fingerprint || '');
const noChange = changed ? 0 : (NAV_ACTIONS.includes(lastAction) ? prevNoChange + 1 : prevNoChange);
let changeNote = 'это первый шаг';
if (st.last_fingerprint !== undefined && lastAction) {
  if (!lastUrl && url) changeNote = `страница открыта: ${cut(url, 80)}`;
  else if (lastUrl && url !== lastUrl) changeNote = 'адрес изменился';
  else if (changed) changeNote = 'содержимое страницы изменилось';
  else if (NAV_ACTIONS.includes(lastAction)) changeNote = 'страница НЕ изменилась — выбери другой элемент или подожди';
  else changeNote = 'без изменений';
}
const staleCount = res.fresh === false ? Number(st.stale_count || 0) + 1 : 0;

let waitsInRow = 0;
for (let i = signatures.length - 1; i >= 0 && signatures[i].startsWith('wait|'); i--) waitsInRow++;

// ===== Остановка по защите =====
let stopReason = '';
if (mode === 'chat' && batch && doneCount >= targetCount) stopReason = `Готово: отправлено ${doneCount} из ${targetCount} ответов`;
else if (step >= maxSteps) stopReason = 'Достигнут лимит шагов';
else if (noChange >= 3) stopReason = 'Страница не меняется после действий (клик не срабатывает?)';
else if (blocked) stopReason = 'Нужна капча или подтверждение — пройдите вручную в браузере';
else if (staleCount >= 3) stopReason = 'Расширение не присылает состояние страницы (остановлено?)';

// ===== Маршрутизация =====
const rule = (action, id, why, extra) => ({ route: 'rule', rule_action: Object.assign({ action, id: id || 0, text: '', url: '', why }, extra || {}) });
const goDecide = (hint) => ({ route: 'decide', hint: hint || '' });
const label = (e) => cut(e.label || e.dq || e.kind, 40);

function findApplyButton() {
  const cands = els.filter((e) => (e.kind === 'link' || e.kind === 'button') && !e.dis);
  return cands.find((e) => APPLY_DQ_RE.test(e.dq || '')) || cands.find((e) => APPLY_RE.test(e.label || ''));
}

function routeForm() {
  const hasDlg = els.some((e) => e.dlg);
  const scope = hasDlg ? els.filter((e) => e.dlg) : els;
  const textFields = scope.filter((e) => e.kind === 'text' && !e.dis);
  const letterLike = (e) => LETTER_FIELD_RE.test(`${e.dq || ''} ${e.label || ''}`);
  const letterField = textFields.find(letterLike);

  // письмо спрятано за кнопкой «добавить сопроводительное»
  if (!letterField && !st.letter_toggled && (WRITE_LETTER_ALWAYS || LETTER_REQUIRED_RE.test(pageText))) {
    const tg = scope.find((e) => ['button', 'link', 'checkbox'].includes(e.kind) && !e.dis && LETTER_TOGGLE_RE.test(`${e.dq || ''} ${e.label || ''}`));
    if (tg) return rule('click', tg.id, 'открываю поле письма');
  }

  // что нужно заполнить (берём первое по порядку на странице)
  const todo = [];
  for (const e of textFields) {
    if (!isEmpty(e)) continue;
    if ((typeCounts[e.sel] || 0) >= MAX_TYPE_ATTEMPTS) return rule('skip', 0, 'не удалось заполнить поле');
    todo.push({ id: e.id, kind: letterLike(e) ? 'letter' : 'answer', e });
  }
  const groups = {};
  for (const e of scope.filter((x) => x.kind === 'radio' && x.grp)) (groups[e.grp] = groups[e.grp] || []).push(e);
  for (const g of Object.values(groups)) {
    if (g.some((r) => r.chk)) continue;
    todo.push({ id: g[0].id, kind: 'choice', e: g[0], options: g.map((r) => ({ id: r.id, label: r.label })), q: g[0].q });
  }
  for (const e of scope.filter((x) => x.kind === 'select' && !x.dis && isEmpty(x))) {
    todo.push({ id: e.id, kind: 'choice', e, select: true, options: (e.opts || []).map((o, i) => ({ id: e.id, label: o })), q: e.q || e.label });
  }
  todo.sort((a, b) => a.id - b.id);
  if (todo.length) {
    const t = todo[0];
    return { route: 'write', write: { kind: t.kind, target_id: t.id, options: t.options || [], select: !!t.select, q: t.q || t.e.q || t.e.label || '' } };
  }

  // всё заполнено — отправляем
  const subs = scope.filter((e) => (e.kind === 'button' || e.kind === 'link') && !e.dis && SUBMIT_RE.test(e.label || ''));
  if (subs.length) return rule('click', subs[subs.length - 1].id, 'отправляю отклик');
  return goDecide('Поля заполнены, но кнопка отправки не найдена');
}

function routeApply() {
  if (autoDone) return rule('done', 0, 'найдено подтверждение отклика');
  if (!url) return rule('open_url', 0, 'открываю список', { url: st.list_url || st.start_url });
  if (vacId) {
    if (!engaged) {
      if (successSeen) return rule('skip', 0, 'уже откликались');
      const btn = findApplyButton();
      if (btn) return rule('click', btn.id, 'нажимаю «откликнуться»');
      return goDecide('На странице вакансии не найдена кнопка отклика');
    }
    return routeForm();
  }
  if (itemLinks.length) return rule('click', itemLinks[0].id, 'открываю вакансию');
  const next = els.find((e) => (e.kind === 'link' || e.kind === 'button') && !e.dis && (NEXT_DQ_RE.test(e.dq || '') || NEXT_RE.test(e.label || '')));
  if (next) return rule('click', next.id, 'следующая страница списка');
  if (pageKind === 'список вакансий') return rule('finish', 0, 'вакансий больше нет', { force: true });
  const recent = signatures.slice(-2).filter((s) => s.startsWith('open_url|')).length;
  if (recent < 2) return rule('open_url', 0, 'возвращаюсь к списку', { url: st.list_url || st.start_url });
  return goDecide('Неизвестная страница');
}

function routeChat() {
  if (!url) return rule('open_url', 0, 'открываю мессенджер', { url: st.start_url });
  const input = els.find((e) => e.kind === 'text' && !e.dis && (e.ce || CHAT_INPUT_RE.test(e.label || '')));
  if (!input) return goDecide('Не найдено поле ввода сообщения — открой нужный чат');
  const lastSent = normText(st.last_sent).slice(-40);
  if (lastSent && normText(tail).endsWith(lastSent)) {
    if (Number(st.chat_waits || 0) >= CHAT_MAX_WAITS) return rule('finish', 0, 'собеседник не отвечает', { force: true });
    return rule('wait', 0, 'chat: жду ответ собеседника');
  }
  return { route: 'write', write: { kind: 'chat', target_id: input.id, options: [], q: '' } };
}

function routeBrowse() {
  if (!url && st.start_url) return rule('open_url', 0, 'открываю стартовую страницу', { url: st.start_url });
  return goDecide('');
}

let decision;
if (stopReason) decision = { route: 'stop' };
else if (mode === 'apply') decision = routeApply();
else if (mode === 'chat') decision = routeChat();
else decision = routeBrowse();

// ===== Промпты (минимум данных) =====
const KIND_RU = { link: 'ссылка', button: 'кнопка', text: 'поле', search: 'поиск', select: 'список', radio: 'выбор', checkbox: 'флажок', file: 'файл', other: 'элемент' };
function lineOf(e) {
  let s = `${e.id}. [${KIND_RU[e.kind] || e.kind}] ${cut(e.label || e.dq || '', 50)}`;
  if (e.kind === 'text' || e.kind === 'search') s += e.value ? ` = "${cut(e.value, 30)}"` : ' (пусто)';
  if (e.kind === 'link' && e.href) s += ` → ${cut(pathOf(e.href), 40)}`;
  if (e.dis) s += ' (недоступно)';
  return s;
}

let decidePrompt = '';
let writerPrompt = '';
if (decision.route === 'decide') {
  const prio = els.filter((e) => e.dlg || e.kind !== 'link').slice(0, DECIDE_MAX_ELEMENTS);
  const links = els.filter((e) => e.kind === 'link' && !e.dlg).slice(0, DECIDE_MAX_LINKS);
  const shown = prio.concat(links).slice(0, DECIDE_MAX_ELEMENTS).sort((a, b) => a.id - b.id);
  const modeHint = { apply: 'идёт отклик на вакансии; если не знаешь, что делать — skip', chat: 'идёт переписка в чате', browse: 'обычная задача' }[mode] || '';
  decidePrompt = [
    `ЦЕЛЬ: ${cut(st.goal || st.user_request, 220)}`,
    `РЕЖИМ: ${modeHint}`,
    `АДРЕС: ${cut(url || '(браузер пуст)', 100)}`,
    `СТРАНИЦА: ${cut(title, 80)}`,
    `ПОСЛЕДНИЕ ДЕЙСТВИЯ:\n${history.length ? history.slice(-HISTORY_SHOWN).join('\n') : '(пока нет)'}`,
    `ИЗМЕНЕНИЯ: ${changeNote}`,
    decision.hint ? `ПОДСКАЗКА: ${decision.hint}` : '',
    `ЭЛЕМЕНТЫ:\n${shown.length ? shown.map(lineOf).join('\n') : '(на странице нет элементов — подожди)'}`,
    'Выбери одно действие.'
  ].filter(Boolean).join('\n');
}

if (decision.route === 'write') {
  const w = decision.write;
  const vac = cut(title + (h1 && !title.includes(h1) ? ' / ' + h1 : ''), 160);
  let task;
  if (w.kind === 'letter') task = `ЗАДАЧА: напиши сопроводительное письмо к вакансии.\nВАКАНСИЯ: ${vac}\nКРИТЕРИИ ПОИСКА: ${cut(st.criteria, 150) || '-'}`;
  else if (w.kind === 'answer') task = `ЗАДАЧА: ответь на вопрос работодателя от имени кандидата (1–3 предложения, только суть).\nВОПРОС: ${cut(w.q, 300)}\nВАКАНСИЯ: ${vac}`;
  else if (w.kind === 'choice') task = `ЗАДАЧА: выбери вариант ответа от имени кандидата. Ответь ТОЛЬКО номером варианта.\nВОПРОС: ${cut(w.q, 300)}\nВАРИАНТЫ:\n${w.options.map((o, i) => `${i + 1}. ${cut(o.label, 80)}`).join('\n')}`;
  else task = `ЗАДАЧА: ответь на последнее сообщение собеседника (например, чат-бота) от имени кандидата.\nПЕРЕПИСКА (конец):\n${cut(tail, 600)}`;
  writerPrompt = `${task}\n\nПРОФИЛЬ КАНДИДАТА:\n${cut(String(st.candidate_profile || '(не указан)'), PROFILE_CHARS)}${st.writer_rules ? '\n\nСТИЛЬ И ПРИМЕР ПИСЬМА:\n' + cut(st.writer_rules, 1200) : ''}`;
}

const compactEls = els.map((e) => ({ id: e.id, kind: e.kind, tag: e.tag, label: e.label, sel: e.sel, dq: e.dq, href: e.href, value: e.value, ce: e.ce }));

return {
  json: {
    ...st,
    history_of_actions: history,
    signatures,
    visited_ids: visited,
    type_counts: typeCounts,
    step,
    max_steps: maxSteps,
    batch,
    done_count: doneCount,
    skipped_count: skippedCount,
    route: decision.route,
    rule_action: decision.rule_action || null,
    write: decision.write || null,
    writer_prompt: writerPrompt,
    decide_prompt: decidePrompt,
    limit_reached: stopReason !== '',
    stop_reason: stopReason,
    current_url: url,
    page_kind: pageKind,
    vac_id: vacId,
    auto_done: autoDone,
    els: compactEls,
    fingerprint,
    no_change_count: noChange,
    stale_count: staleCount,
    change_note: changeNote,
    waits_in_row: waitsInRow,
    tail,
    page_title: title
  }
};

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "action": {
      "type": "string",
      "enum": [
        "open_url",
        "click",
        "type",
        "wait",
        "skip",
        "finish"
      ]
    },
    "id": {
      "type": "integer",
      "description": "Номер элемента из списка (click/type), иначе 0."
    },
    "text": {
      "type": "string",
      "description": "Текст для type, иначе пустая строка."
    },
    "url": {
      "type": "string",
      "description": "Адрес для open_url, иначе пустая строка."
    }
  },
  "required": [
    "action",
    "id",
    "text",
    "url"
  ]
}

parameters.jsCode:
const getCtx = (name) => {
  let lastErr;
  for (const suffix of ['', '1', '2', '3', '4', '5']) {
    const n = name + suffix;
    try { return $(n).item.json; } catch (e) { lastErr = e; }
    try { return $(n).first().json; } catch (e) { lastErr = e; }
  }
  throw lastErr;
};

const ITEM_HREF_RE = /\/vacancy\/(\d+)/;
const LETTER_TOGGLE_RE = /(((написать|добавить|приложить|write|add|attach).{0,30}(сопроводит|cover))|letter-toggle)/i;

// Какие поля состояния переходят на следующий шаг
const STATE_KEYS = [
  'user_request', 'mode', 'goal', 'start_url', 'target_count', 'criteria', 'candidate_profile', 'writer_rules',
  'history_of_actions', 'signatures', 'step', 'done_count', 'skipped_count', 'visited_ids',
  'current_vacancy_id', 'engaged', 'list_url', 'letter_toggled', 'type_counts', 'last_sent', 'chat_waits',
  'stale_count', 'last_action', 'last_fingerprint', 'last_url', 'no_change_count'
];

const ctx = getCtx('Анализ страницы');
const inp = $input.item.json || {};
const out = inp.output;
const mode = ctx.mode;
const batch = !!ctx.batch;
const elMap = {};
for (const e of ctx.els || []) elMap[e.id] = e;

const cut = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; };

// ===== 1. Откуда пришло решение =====
function sanitize(t, kind) {
  t = String(t || '').trim()
    .replace(/^["«“'`]+|["»”'`]+$/g, '')
    .replace(/^(ответ|письмо|сообщение|answer|reply)\s*[:\-]\s*/i, '')
    .replace(/\n{3,}/g, '\n\n').trim();
  return cut(t, { letter: 1200, answer: 400, chat: 500 }[kind] || 400);
}

function fromWriter(o) {
  const w = ctx.write || {};
  let t = typeof o === 'string' ? o : (o && (o.text || o.output)) || '';
  t = String(t).trim();
  if (w.kind === 'choice') {
    const m = t.match(/\d+/);
    const opt = m ? (w.options || [])[Number(m[0]) - 1] : null;
    if (!opt) return { action: 'wait', why: 'писатель не выбрал вариант', bad: 'писатель не выбрал вариант' };
    return w.select ? { action: 'type', id: w.target_id, text: opt.label, why: 'выбираю вариант' } : { action: 'click', id: opt.id, why: 'выбираю вариант' };
  }
  if (/НЕТ[_ ]ДАННЫХ|NO[_ ]DATA/i.test(t)) return { action: 'skip', why: 'в профиле нет данных для ответа', trusted: true };
  t = sanitize(t, w.kind);
  if (!t) return { action: 'wait', why: 'писатель вернул пустой текст', bad: 'писатель вернул пустой текст' };
  return { action: 'type', id: w.target_id, text: t, enter: w.kind === 'chat', why: w.kind === 'letter' ? 'пишу сопроводительное' : (w.kind === 'chat' ? 'отвечаю в чате' : 'отвечаю на вопрос') };
}

function fromDecider(o) {
  if (!o || typeof o !== 'object') return { action: 'wait', why: 'нет решения', bad: 'модель не вернула решение' };
  return { action: String(o.action || '').toLowerCase(), id: Number(o.id) || 0, text: String(o.text || ''), url: String(o.url || ''), why: 'решение модели' };
}

let act;
if (ctx.route === 'rule') act = Object.assign({ text: '', url: '' }, ctx.rule_action, { trusted: true });
else if (ctx.route === 'write') act = fromWriter(out);
else act = fromDecider(out);

let action = act.action;
let id = act.id || 0;
let text = act.text || '';
let url = act.url || '';
let note = act.bad || '';
let rejected = !!act.bad;
const reject = (msg) => { note = msg; rejected = true; action = 'wait'; id = 0; text = ''; url = ''; };

// ===== 2. Проверка решения =====
const VALID = ['open_url', 'click', 'type', 'wait', 'skip', 'done', 'finish'];
if (!rejected && !VALID.includes(action)) reject(`неизвестное действие "${action}"`);

let el = null;
if (!rejected && (action === 'click' || action === 'type')) {
  el = elMap[id];
  if (!el) reject(`элемента с номером ${id} нет в списке`);
  else if (action === 'click' && (el.kind === 'text' || el.kind === 'search') && !act.trusted) reject('это поле ввода — выбери type');
  else if (action === 'type' && !['text', 'search', 'select'].includes(el.kind)) reject('в этот элемент нельзя вводить текст');
  else if (action === 'type' && !text) reject('не указан текст для ввода');
}

if (!rejected && action === 'open_url') {
  if (url && !/^https?:\/\//i.test(url)) url = 'https://' + url.replace(/^\/+/, '');
  const norm = (u) => (u || '').replace(/#.*$/, '').replace(/\/+$/, '').toLowerCase();
  if (!/^https?:\/\/[^\s\/]+\.[^\s]+/i.test(url)) reject(`open_url без корректного URL ("${url}")`);
  else if (ctx.els.length > 0 && norm(url) === norm(ctx.current_url)) reject('этот адрес уже открыт');
}

if (!rejected && (action === 'done' || action === 'skip')) {
  if (mode !== 'apply' || !batch) reject('done/skip работают только в режиме откликов');
  else if (!ctx.vac_id && !act.trusted) reject('сейчас не открыта вакансия');
}

if (!rejected && action === 'finish' && batch && !act.force) {
  reject(`осталось ${Number(ctx.target_count) - Number(ctx.done_count)} из ${ctx.target_count}; finish только когда вакансий больше нет`);
}

// ===== 3. Защита от зацикливания =====
const sigTarget = el ? el.sel : url;
const sig = rejected ? `rejected|${note}` : [action, sigTarget, cut(text, 40)].join('|');
const sigs = (ctx.signatures || []).concat(sig).slice(-8);
const lastN = (n) => sigs.slice(-n);
const repeated = action !== 'wait' && lastN(4).length === 4 && lastN(4).every((s) => s === sig);
const rejectedRepeat = rejected && lastN(3).length === 3 && lastN(3).every((s) => s === sig);
let waitsInRow = 0;
for (let i = sigs.length - 1; i >= 0 && sigs[i].startsWith('wait|'); i--) waitsInRow++;
const chatWait = mode === 'chat' && action === 'wait' && !rejected;
const stuck = repeated || rejectedRepeat || (!chatWait && waitsInRow >= 4);

// ===== 4. Обновление состояния =====
const state = {};
for (const k of STATE_KEYS) if (ctx[k] !== undefined) state[k] = ctx[k];

let done = Number(ctx.done_count || 0);
let skipped = Number(ctx.skipped_count || 0);
let visited = (ctx.visited_ids || []).map(String);
let engaged = !!ctx.engaged;
let listUrl = ctx.list_url || ctx.start_url || '';
let currentVac = ctx.vac_id || '';
let letterToggled = !!ctx.letter_toggled;
const typeCounts = Object.assign({}, ctx.type_counts || {});
let lastSent = ctx.last_sent || '';
let chatWaits = Number(ctx.chat_waits || 0);

if (action === 'click' && el) {
  if (!ctx.vac_id && el.kind === 'link' && el.href && ITEM_HREF_RE.test(el.href)) listUrl = ctx.current_url; // запоминаем список
  if (LETTER_TOGGLE_RE.test(`${el.dq || ''} ${el.label || ''}`)) letterToggled = true;
}
if (action === 'type' && el) {
  typeCounts[el.sel] = (typeCounts[el.sel] || 0) + 1;
  if (mode === 'chat') { lastSent = text; done++; chatWaits = 0; }
}
if ((action === 'click' || action === 'type') && ctx.vac_id) engaged = true;
if (chatWait) chatWaits++;

const closesItem = action === 'done' || action === 'skip';
if (closesItem) {
  const vid = String(ctx.vac_id || '');
  if (vid && !visited.includes(vid)) visited.push(vid);
  visited = visited.slice(-2000);
  if (action === 'done') done++; else skipped++;
  engaged = false; currentVac = ''; letterToggled = false;
  for (const k of Object.keys(typeCounts)) delete typeCounts[k];
  try {
    const sd = $getWorkflowStaticData('global'); // сохраняется между запусками активного workflow
    sd.visited_ids = visited;
  } catch (e) { /* в ручном тесте не сохраняется — это нормально */ }
}

// в чате цель проверяет «Анализ страницы» уже ПОСЛЕ отправки последнего сообщения
const reachedTarget = batch && mode === 'apply' && done >= Number(ctx.target_count || 0);
const finished = action === 'finish' || stuck || reachedTarget;

// ===== 5. Запись в историю =====
const stepNo = Number(ctx.step || 0) + 1;
const labelOf = el ? `«${cut(el.label || el.dq, 30)}»` : (url ? cut(url, 50) : '');
const VERB = { open_url: 'открыл', click: 'нажал', type: 'ввёл в', wait: 'подождал', skip: 'пропустил вакансию', done: 'отклик отправлен', finish: 'завершил' };
let line = `Шаг ${stepNo}: ${VERB[action]} ${labelOf}`.trim();
if (note) line += ` ⚠ ${note}`;

// ===== 6. Команда расширению (формат Java DTO ActionResponce) =====
const command = { url_to_open: '', click_selector: '', inputs_to_fill: [] };
if (!finished) {
  if (action === 'open_url') command.url_to_open = url;
  if (action === 'click') command.click_selector = el.sel;
  if (action === 'type') {
    const enter = el.kind === 'search' || act.enter === true;
    command.inputs_to_fill.push({ selector: el.sel, value: text + (enter ? '\n' : '') });
  }
  if (closesItem) command.url_to_open = listUrl; // вернуться к списку
}

const WAIT = { open_url: 1, click: 1.5, type: 1, wait: chatWait ? 8 : 4, skip: 1, done: 1, finish: 0 };

let finalMessage = '';
if (stuck) finalMessage = 'Остановлено: агент зациклился или страница не отвечает';
else if (reachedTarget) finalMessage = `Готово: выполнено ${done} из ${ctx.target_count}, пропущено ${skipped}`;
else if (action === 'finish') finalMessage = act.why || 'Задача выполнена';

return {
  json: {
    ...state,
    history_of_actions: (ctx.history_of_actions || []).concat(line).slice(-12),
    signatures: sigs,
    step: stepNo,
    last_action: action,
    last_fingerprint: ctx.fingerprint,
    last_url: ctx.current_url,
    no_change_count: ctx.no_change_count || 0,
    stale_count: ctx.stale_count || 0,
    done_count: done,
    skipped_count: skipped,
    visited_ids: visited,
    engaged,
    current_vacancy_id: currentVac,
    letter_toggled: letterToggled,
    type_counts: typeCounts,
    list_url: listUrl,
    last_sent: lastSent,
    chat_waits: chatWaits,
    command,
    wait_seconds: rejected ? 1 : WAIT[action],
    finished,
    final_message: finalMessage
  }
};

// После HTTP-запроса в item осталась только ответ сервера — достаём сохранённое состояние
const getCtx = (name) => {
  let lastErr;
  for (const suffix of ['', '1', '2', '3', '4', '5']) {
    const n = name + suffix;
    try { return $(n).item.json; } catch (e) { lastErr = e; }
    try { return $(n).first().json; } catch (e) { lastErr = e; }
  }
  throw lastErr;
};

const s = getCtx('Применить решение');
// всё состояние идёт дальше, кроме одноразовых полей
const { command, finished, final_message, ...state } = s;

return { json: state };

// Итог работы агента (сюда попадают и нормальное завершение, и остановка по защите)
const j = $input.item.json;

return {
  json: {
    result: j.final_message || j.stop_reason || 'Остановлено',
    mode: j.mode || '',
    done_count: j.done_count || 0,
    skipped_count: j.skipped_count || 0,
    target_count: j.target_count || 0,
    steps: j.step || 0,
    history_of_actions: j.history_of_actions || []
  }
};
